const body = $input.first().json.body || {};
const queries = body.queries || {};
const preferredFilenames = body.preferredFilenames || {};
const allKws = new Set();
for (const k of Object.keys(queries)) {
  for (const kw of (queries[k] || [])) {
    const c = String(kw).trim();
    if (c) allKws.add(c);
  }
}
for (const fn of Object.values(preferredFilenames)) {
  const c = String(fn).trim();
  if (c) allKws.add(c);
}
if (allKws.size === 0) return [{ json: { skip: true, queries, preferredFilenames, queryString: "name contains '___nope___'" } }];
const clauses = Array.from(allKws).map(kw => "name contains '" + kw.replace(/'/g, "\\'") + "'");
const queryString = '(' + clauses.join(' or ') + ") and mimeType != 'application/vnd.google-apps.folder' and trashed = false";
return [{ json: { skip: false, queries, preferredFilenames, queryString } }];

const httpRes = $input.first().json;
const bq = $('Build Query').first().json;
const queries = bq.queries || {};
const preferredFilenames = bq.preferredFilenames || {};
const files = httpRes.files || [];
const matches = {};
for (const docKey of Object.keys(queries)) {
  const kws = (queries[docKey] || []).map(s => String(s).toLowerCase()).filter(Boolean);
  const pref = preferredFilenames[docKey];
  if (pref) {
    const exact = files.find(f => String(f.name || '').toLowerCase() === String(pref).toLowerCase());
    if (exact) {
      matches[docKey] = { id: exact.id, name: exact.name, mimeType: exact.mimeType, webViewLink: exact.webViewLink };
      continue;
    }
  }
  if (kws.length === 0) { matches[docKey] = null; continue; }
  const found = files.find(f => {
    const n = String(f.name || '').toLowerCase();
    return kws.some(kw => n.includes(kw));
  });
  matches[docKey] = found ? { id: found.id, name: found.name, mimeType: found.mimeType, webViewLink: found.webViewLink } : null;
}
return [{ json: { success: true, matches, fileCount: files.length } }];
